63	/**
64	 * @author Vitaliy Fedoriv
65	 */
66	
67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    /**
73	     * Syntactic check for an email address: a non-empty local part, an '@', a domain with at least
74	     * one dot and a two-or-more letter top-level label. Case-insensitive; the accepted value is
75	     * stored lower-cased.
76	     */
77	    private static final Pattern EMAIL_PATTERN =
78	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
79	
80	    /** A well-formed postcode: exactly four digits. */
81	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
82	
83	    /**
84	     * Region -&gt; inclusive 4-digit postcode range {@code {low, high}}. A postcode supplied for an
85	     * owner whose city maps to one of these regions (see {@link LocalityLookup}) must fall within the
86	     * region's range; a city with no known region ({@code "UNKNOWN"}) accepts any 4-digit postcode.
87	     */
88	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
89	        "NSW", new int[] {2000, 2099},
90	        "VIC", new int[] {3000, 3099},
91	        "QLD", new int[] {4000, 4099});
92	
93	    /** Dedicated audit logger; one line is emitted per successful owner create. */
94	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
95	
96	    /**
97	     * The maximum number of owners a single city may contain. Once a city already holds this many
98	     * owners, any further create naming that city is rejected as a conflict.
99	     */
100	    private static final int MAX_OWNERS_PER_CITY = 50;
101	
102	    /**
103	     * The maximum number of owners that may be registered in a single day. Once this many owners
104	     * already carry today's registration date, any further create is rejected as too many requests.
105	     */
106	    private static final int MAX_OWNERS_PER_DAY = 100;
107	
108	    /**
109	     * The number of owners that must already be registered on today's business day before a response
110	     * carries a bulk-signup warning. Once more than this many owners already carry today's
111	     * registration date, responses set {@code bulkSignupWarning} true.
112	     */
113	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
114	
115	    private final ClinicService clinicService;
116	
117	    private final OwnerMapper ownerMapper;
118	
119	    private final PetMapper petMapper;
120	
121	    private final VisitMapper visitMapper;
122	
123	    public OwnerRestControllerV1(ClinicService clinicService,
124	                                 OwnerMapper ownerMapper,
125	                                 PetMapper petMapper,
126	                                 VisitMapper visitMapper) {
127	        this.clinicService = clinicService;
128	        this.ownerMapper = ownerMapper;
129	        this.petMapper = petMapper;
130	        this.visitMapper = visitMapper;
131	    }
132	
133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Override
135	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
136	        Collection<Owner> owners;
137	        if (lastName != null) {
138	            owners = this.clinicService.findOwnerByLastName(lastName);
139	        } else {
140	            owners = this.clinicService.findAllOwners();
141	        }
142	        if (owners.isEmpty()) {
143	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
144	        }
145	        owners.forEach(owner -> owner.setHouseholdMemberCount(countHouseholdMembers(owner)));
146	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
147	    }
148	
149	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
150	    @Override
151	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
152	        Owner owner = this.clinicService.findOwnerById(ownerId);
153	        if (owner == null) {
154	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
155	        }
156	        OwnerDto ownerDto = toOwnerDto(owner);
157	        ownerDto.setBulkSignupWarning(isBulkSignupWarningActive());
158	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
159	    }
160	
161	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
162	    @Override
163	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
164	        validateRequiredOwnerFields(ownerFieldsDto);
165	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
166	        LocalDate suppliedOrDefaultDate =
167	            ownerFieldsDto.getRegistrationDate() != null ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
168	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
169	        rejectDailyLimitExceeded(registrationDate);
170	        rejectCityAtCapacity(ownerFieldsDto.getCity());
171	        HttpHeaders headers = new HttpHeaders();
172	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
173	        validatePostcode(owner.getCity(), owner.getPostcode());
174	        owner.setAddress(normalizeAddress(owner.getAddress()));
175	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
176	        owner.setTelephone(normalizedTelephone);
177	        boolean declaredHouseholdMember = applyHousehold(owner, ownerFieldsDto.getSharesHousehold());
178	        owner.setEmail(normalizeEmail(owner.getEmail()));
179	        rejectDuplicateIdentity(owner);
180	        applyPossibleDuplicate(owner, declaredHouseholdMember);
181	        owner.setRegistrationDate(registrationDate);
182	        owner.setCustomerCode(
183	            generateCustomerCode(owner.getPostcode(), owner.getCity(), normalizedTelephone, owner.getLastName()));
184	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
185	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
186	        this.clinicService.saveOwner(owner);
187	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
188	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
189	        OwnerDto ownerDto = toOwnerDto(owner);
190	        ownerDto.setBulkSignupWarning(isBulkSignupWarningActive());
191	        headers.setLocation(UriComponentsBuilder.newInstance()
192	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
193	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
194	    }
195	
196	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
197	    @Override
198	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
199	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
200	        if (currentOwner == null) {
201	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
202	        }
203	        currentOwner.setAddress(ownerFieldsDto.getAddress());
204	        currentOwner.setCity(ownerFieldsDto.getCity());
205	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
206	        currentOwner.setLastName(ownerFieldsDto.getLastName());
207	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
208	        this.clinicService.saveOwner(currentOwner);
209	        return new ResponseEntity<>(toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
210	    }
211	
212	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
213	    @Transactional
214	    @Override
215	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
216	        Owner owner = this.clinicService.findOwnerById(ownerId);
217	        if (owner == null) {
218	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
219	        }
220	        this.clinicService.deleteOwner(owner);
221	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
222	    }
223	
224	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
225	    @Override
226	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
227	        Owner owner = this.clinicService.findOwnerById(ownerId);
228	        if (owner == null) {
229	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
230	        }
231	        HttpHeaders headers = new HttpHeaders();
232	        Pet pet = petMapper.toPet(petFieldsDto);
233	        owner.setId(ownerId);
234	        pet.setOwner(owner);
235	        pet.getType().setName(null);
236	        this.clinicService.savePet(pet);
237	        PetDto petDto = petMapper.toPetDto(pet);
238	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
239	            .buildAndExpand(pet.getId()).toUri());
240	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
241	    }
242	
243	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
244	    @Override
245	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
246	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
247	        if (currentOwner != null) {
248	            Pet currentPet = this.clinicService.findPetById(petId);
249	            if (currentPet != null) {
250	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
251	                currentPet.setName(petFieldsDto.getName());
252	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
253	                this.clinicService.savePet(currentPet);
254	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
255	            }
256	        }
257	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
258	    }
259	
260	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
261	    @Override
262	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
263	        HttpHeaders headers = new HttpHeaders();
264	        Visit visit = visitMapper.toVisit(visitFieldsDto);
265	        Pet pet = new Pet();
266	        pet.setId(petId);
267	        visit.setPet(pet);
268	        this.clinicService.saveVisit(visit);
269	        VisitDto visitDto = visitMapper.toVisitDto(visit);
270	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
271	            .buildAndExpand(visit.getId()).toUri());
272	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
273	    }
274	
275	
276	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
277	    @Override
278	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
279	        Owner owner = this.clinicService.findOwnerById(ownerId);
280	        if (owner != null) {
281	            Pet pet = owner.getPet(petId);
282	            if (pet != null) {
283	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
284	            }
285	        }
286	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
287	    }
288	
289	    /**
290	     * Rejects an owner whose mandatory fields are missing (null) or blank. The name of every
291	     * offending field is collected so the caller learns exactly which values must be supplied.
292	     *
293	     * @param ownerFieldsDto the submitted owner payload
294	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or
295	     *         telephone is missing or blank
296	     */
297	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
298	        List<String> missingFields = new ArrayList<>();
299	        if (isBlank(ownerFieldsDto.getFirstName())) {
300	            missingFields.add("firstName");
301	        }
302	        if (isBlank(ownerFieldsDto.getLastName())) {
303	            missingFields.add("lastName");
304	        }
305	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
306	            missingFields.add("address");
307	        }
308	        if (isBlank(ownerFieldsDto.getCity())) {
309	            missingFields.add("city");
310	        }
311	        if (isBlank(ownerFieldsDto.getTelephone())) {
312	            missingFields.add("telephone");
313	        }
314	        if (!missingFields.isEmpty()) {
315	            throw new MissingOwnerFieldsException(missingFields);
316	        }
317	    }
318	
319	    private boolean isBlank(String value) {
320	        return value == null || value.isBlank();
321	    }
322	
323	    /**
324	     * Rejects an owner create whose supplied {@code registrationDate} is later than the server's
325	     * current date. A registration date may not lie in the future; a value equal to today or in the
326	     * past is accepted, and an absent date is left to default to the server date.
327	     *
328	     * @param registrationDate the supplied registration date, or {@code null} when none was supplied
329	     * @throws InvalidOwnerFieldsException if the supplied date is after the server's current date
330	     */
331	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
332	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
333	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
334	        }
335	    }
336	
337	    /**
338	     * Counts the existing owners who, before this create, already share the given first and last name.
339	     * Both names are compared case-insensitively (after trimming surrounding whitespace and collapsing
340	     * internal runs of whitespace, mirroring the other name comparisons), so cosmetic differences in
341	     * case or spacing still count as the same name.
342	     *
343	     * @param firstName the first name of the owner being created
344	     * @param lastName the last name of the owner being created
345	     * @return the number of existing owners sharing both names (zero when none)
346	     */
347	    private int countNamesakes(String firstName, String lastName) {
348	        String first = normalizeHouseholdField(firstName);
349	        String last = normalizeHouseholdField(lastName);
350	        return (int) this.clinicService.findAllOwners().stream()
351	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(first)
352	                && normalizeHouseholdField(existing.getLastName()).equals(last))
353	            .count();
354	    }
355	
356	    /**
357	     * Rejects an owner create whose city already holds the maximum number of owners. Owners are
358	     * grouped into a city case-insensitively after surrounding whitespace is trimmed and internal
359	     * runs are collapsed (mirroring the other city comparisons), so cosmetic differences in case or
360	     * spacing count as the same city. When the city already contains {@link #MAX_OWNERS_PER_CITY} or
361	     * more owners the create is rejected as a conflict.
362	     *
363	     * @param city the city of the owner being created
364	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
365	     */
366	    /**
367	     * Rejects an owner create once the maximum number of owners have already been registered on the
368	     * business day this owner would land on. Owners are grouped by their {@code registrationDate},
369	     * which is always a business day (a weekend effective date is rolled forward to the following
370	     * Monday); when {@link #MAX_OWNERS_PER_DAY} or more existing owners already carry the given
371	     * business day the create is rejected as too many requests. Because a weekend effective date is
372	     * rolled forward, this quota bounds the number of owners that may be registered per business day.
373	     *
374	     * @param businessDay the adjusted business day the owner being created would be registered on
375	     * @throws OwnerDailyLimitExceededException if the business day already holds the maximum number of owners
376	     */
377	    private void rejectDailyLimitExceeded(LocalDate businessDay) {
378	        long ownersOnDay = this.clinicService.findAllOwners().stream()
379	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
380	            .count();
381	        if (ownersOnDay >= MAX_OWNERS_PER_DAY) {
382	            throw new OwnerDailyLimitExceededException(businessDay, MAX_OWNERS_PER_DAY);
383	        }
384	    }
385	
386	    /**
387	     * Rolls an effective registration date forward onto a business day. A Saturday or Sunday is moved
388	     * forward to the following Monday; a weekday is returned unchanged. This applies whether the date
389	     * was supplied on the request or defaulted to the server's current date.
390	     *
391	     * @param date the effective registration date (supplied or defaulted)
392	     * @return the same date when it is a weekday, otherwise the following Monday
393	     */
394	    /**
395	     * Reports whether responses should carry a bulk-signup warning. The warning is active once more
396	     * than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry today's business-day
397	     * registration date (the same accumulation basis as the per-day create limit), signalling that the
398	     * daily create volume is approaching {@link #MAX_OWNERS_PER_DAY}.
399	     *
400	     * @return {@code true} when more than the threshold number of owners are already registered on
401	     *         today's business day, otherwise {@code false}
402	     */
403	    private boolean isBulkSignupWarningActive() {
404	        LocalDate today = toBusinessDay(LocalDate.now());
405	        long ownersToday = this.clinicService.findAllOwners().stream()
406	            .filter(existing -> today.equals(existing.getRegistrationDate()))
407	            .count();
408	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
409	    }
410	
411	    private LocalDate toBusinessDay(LocalDate date) {
412	        return switch (date.getDayOfWeek()) {
413	            case SATURDAY -> date.plusDays(2);
414	            case SUNDAY -> date.plusDays(1);
415	            default -> date;
416	        };
417	    }
418	
419	    private void rejectCityAtCapacity(String city) {
420	        String normalizedCity = normalizeHouseholdField(city);
421	        long ownersInCity = this.clinicService.findAllOwners().stream()
422	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalizedCity))
423	            .count();
424	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
425	            throw new OwnerCityCapacityExceededException(city, MAX_OWNERS_PER_CITY);
426	        }
427	    }
428	
429	    /**
430	     * Builds an owner's customer code, formatted '&lt;REGION&gt;-&lt;HASH8&gt;'. REGION is the region
431	     * code derived from the owner's postcode (falling back to their city; see {@link LocalityLookup}),
432	     * and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over the owner's
433	     * normalized telephone concatenated with their last name (e.g. 'NSW-1A2B3C4D'). The code carries no
434	     * sequence number; two owners resolve to the same code only when they share a region and produce the
435	     * same telephone-and-last-name hash.
436	     *
437	     * @param postcode the owner's postcode, used first to derive the region
438	     * @param city the owner's city, used to derive the region when the postcode maps to none
439	     * @param normalizedTelephone the owner's normalized (E.164) telephone
440	     * @param lastName the owner's last name
441	     * @return the formatted customer code
442	     */
443	    private String generateCustomerCode(String postcode, String city, String normalizedTelephone, String lastName) {
444	        String region = LocalityLookup.forPostcodeAndCity(postcode, city);
445	        String hash8 = sha256UpperHex(normalizedTelephone + lastName, 8);
446	        return region + "-" + hash8;
447	    }
448	
449	    /**
450	     * Builds an owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where
451	     * customerCode is the owner's customer code and YY is the last two digits of the
452	     * registrationDate year (e.g. 'NSW-1A2B3C4D-M26').
453	     *
454	     * @param customerCode the owner's customer code
455	     * @param registrationDate the owner's registration date
456	     * @return the formatted membership number
457	     */
458	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
459	        String yy = String.format("%02d", registrationDate.getYear() % 100);
460	        return customerCode + "-M" + yy;
461	    }
462	
463	    /**
464	     * The exact number of national (subscriber) digits an E.164 telephone must carry for a given
465	     * country calling code. Australia ('+61') uses 9 national digits and the North American
466	     * Numbering Plan ('+1') uses 10. Country codes not listed here are only bound by the generic
467	     * E.164 length (8 to 15 digits overall).
468	     */
469	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
470	        java.util.Map.of("61", 9, "1", 10);
471	
472	    /**
473	     * Normalizes a telephone number supplied on create into E.164 form. Spaces, dashes and brackets
474	     * are stripped. When the value carries an explicit leading '+' its country code is kept as given;
475	     * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
476	     * digits. The result must be a '+' followed by 8 to 15 digits, and its national number must have
477	     * the exact length its country code requires ('+61' needs 9 national digits, '+1' needs 10). This
478	     * E.164 string is what gets stored and returned.
479	     *
480	     * @param telephone the raw telephone value from the request
481	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
482	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number or its
483	     *         national number has the wrong length for its country code
484	     */
485	    private String normalizeTelephone(String telephone) {
486	        String cleaned = telephone == null ? "" : telephone.trim().replaceAll("[\\s()\\-]", "");
487	        String e164;
488	        if (cleaned.startsWith("+")) {
489	            e164 = cleaned;
490	        } else {
491	            String national = cleaned;
492	            if (national.startsWith("0")) {
493	                national = national.substring(1);
494	            }
495	            e164 = "+61" + national;
496	        }
497	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
498	            throw new InvalidOwnerFieldsException(List.of("telephone"));
499	        }
500	        validateNationalNumberLength(e164);
501	        return e164;
502	    }
503	
504	    /**
505	     * Rejects an E.164 telephone whose national number does not have the exact length its country
506	     * calling code requires. The digits after the leading '+' are split into the longest matching
507	     * country code from {@link #NATIONAL_NUMBER_LENGTHS} and the remaining national number; when the
508	     * code is known and the national number's length differs from the required count the telephone is
509	     * rejected. Numbers whose country code is not listed are left to the generic E.164 length rule.
510	     *
511	     * @param e164 the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
512	     * @throws InvalidOwnerFieldsException if the national number has the wrong length for its country code
513	     */
514	    private void validateNationalNumberLength(String e164) {
515	        String digits = e164.substring(1);
516	        for (int codeLength = Math.min(3, digits.length()); codeLength >= 1; codeLength--) {
517	            String countryCode = digits.substring(0, codeLength);
518	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
519	            if (requiredNationalLength != null) {
520	                int nationalLength = digits.length() - codeLength;
521	                if (nationalLength != requiredNationalLength) {
522	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
523	                }
524	                return;
525	            }
526	        }
527	    }
528	
529	    /**
530	     * Normalizes an optional email address supplied on create. An absent email (null or blank) is
531	     * left unset. When a value is present it must be a syntactically valid address; the normalized
532	     * form stored and returned is the value lower-cased.
533	     *
534	     * @param email the raw email value from the request, or {@code null} when none was supplied
535	     * @return the lower-cased email, or {@code null} when no email was supplied
536	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
537	     */
538	    private String normalizeEmail(String email) {
539	        if (email == null || email.isBlank()) {
540	            return null;
541	        }
542	        if (!EMAIL_PATTERN.matcher(email).matches()) {
543	            throw new InvalidOwnerFieldsException(List.of("email"));
544	        }
545	        return email.toLowerCase(Locale.ROOT);
546	    }
547	
548	    /**
549	     * Validates an optional postcode supplied on create. A postcode is validated only when present:
550	     * an absent (null or blank) postcode is accepted, keeping the create request backward-compatible.
551	     * When present it must be exactly four digits and, when the owner's city maps to a known region
552	     * (see {@link LocalityLookup}), must fall within that region's inclusive range
553	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known
554	     * region accepts any four-digit postcode.
555	     *
556	     * @param city the owner's city, used to derive the region whose range the postcode must satisfy
557	     * @param postcode the raw postcode value from the request, or {@code null} when none was supplied
558	     * @throws InvalidOwnerFieldsException if a supplied postcode is not four digits or is out of range
559	     *         for the city's region
560	     */
561	    private void validatePostcode(String city, String postcode) {
562	        if (postcode == null || postcode.isBlank()) {
563	            return;
564	        }
565	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
566	            throw new InvalidOwnerFieldsException(List.of("postcode"));
567	        }
568	        int[] range = REGION_POSTCODE_RANGES.get(LocalityLookup.forCity(city));
569	        if (range == null) {
570	            return;
571	        }
572	        int value = Integer.parseInt(postcode);
573	        if (value < range[0] || value > range[1]) {
574	            throw new InvalidOwnerFieldsException(List.of("postcode"));
575	        }
576	    }
577	
578	    /**
579	     * Normalizes an address supplied on create. Surrounding whitespace is trimmed, each internal run
580	     * of whitespace is collapsed to a single space, the value is upper-cased and common abbreviations
581	     * are expanded to their full words (ST -&gt; STREET, RD -&gt; ROAD, AVE -&gt; AVENUE). This
582	     * normalized form is what gets stored, returned and used for every address comparison (the
583	     * required-field check, household duplicate detection and the shared household id).
584	     *
585	     * @param address the raw address value from the request, or {@code null}
586	     * @return the normalized address (empty string when {@code address} is {@code null} or blank)
587	     */
588	    private String normalizeAddress(String address) {
589	        if (address == null) {
590	            return "";
591	        }
592	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
593	        if (collapsed.isEmpty()) {
594	            return "";
595	        }
596	        String[] tokens = collapsed.split(" ");
597	        for (int i = 0; i < tokens.length; i++) {
598	            switch (tokens[i]) {
599	                case "ST" -> tokens[i] = "STREET";
600	                case "RD" -> tokens[i] = "ROAD";
601	                case "AVE" -> tokens[i] = "AVENUE";
602	                default -> { }
603	            }
604	        }
605	        return String.join(" ", tokens);
606	    }
607	
608	    /**
609	     * Rejects an owner create whose {@code identityKey} exactly matches an existing owner's. The
610	     * identity key - the owner's normalized telephone, email (empty when none) and {@code householdId}
611	     * (empty when none) joined by {@code '|'} - is the single derived value that subsumes the former
612	     * separate telephone, email and household duplicate checks. Only a whole-key match is a conflict,
613	     * so two members of one household with different telephones have different keys and are both
614	     * allowed; only an owner whose entire key is identical is a duplicate.
615	     *
616	     * @param owner the owner being created, with its telephone, email and householdId already resolved
617	     * @throws DuplicateOwnerIdentityException if another owner already has this exact identity key
618	     */
619	    private void rejectDuplicateIdentity(Owner owner) {
620	        String identityKey = owner.getIdentityKey();
621	        boolean inUse = this.clinicService.findAllOwners().stream()
622	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
623	        if (inUse) {
624	            throw new DuplicateOwnerIdentityException(identityKey);
625	        }
626	    }
627	
628	    /**
629	     * Flags an owner being created as a possible (soft) duplicate. A soft match is an existing owner
630	     * that shares this owner's last name (compared case-insensitively with collapsed whitespace) and
631	     * postcode but carries a different (normalized) telephone; such an owner is not a hard duplicate
632	     * (its identity key differs) and is still created. When at least one soft match exists,
633	     * {@code possibleDuplicate} is set true and {@code possibleDuplicateOf} to the lowest-id match;
634	     * otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is left unset.
635	     * <p>
636	     * A declared household member - an owner that acknowledged sharing an existing household via
637	     * {@code sharesHousehold} - is never flagged: having deliberately joined the household it is not a
638	     * suspected duplicate, so {@code possibleDuplicate} is set false without inspecting other owners.
639	     *
640	     * @param owner the owner being created, with its last name, postcode and normalized telephone resolved
641	     * @param declaredHouseholdMember whether the owner joined an existing household by acknowledging it
642	     */
643	    private void applyPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
644	        if (declaredHouseholdMember) {
645	            owner.setPossibleDuplicate(false);
646	            return;
647	        }
648	        String lastName = normalizeHouseholdField(owner.getLastName());
649	        String postcode = owner.getPostcode();
650	        String telephone = owner.getTelephone();
651	        Owner match = null;
652	        if (postcode != null && !postcode.isBlank()) {
653	            match = this.clinicService.findAllOwners().stream()
654	                .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName))
655	                .filter(existing -> postcode.equals(existing.getPostcode()))
656	                .filter(existing -> !java.util.Objects.equals(telephone, existing.getTelephone()))
657	                .min(java.util.Comparator.comparing(Owner::getId))
658	                .orElse(null);
659	        }
660	        if (match != null) {
661	            owner.setPossibleDuplicate(true);
662	            owner.setPossibleDuplicateOf(match.getId());
663	        } else {
664	            owner.setPossibleDuplicate(false);
665	        }
666	    }
667	
668	    /**
669	     * Maps an owner to its DTO, first populating the owner's {@link Owner#getHouseholdMemberCount()
670	     * household member count} for the response.
671	     *
672	     * @param owner the owner to map
673	     * @return the mapped owner DTO
674	     */
675	    private OwnerDto toOwnerDto(Owner owner) {
676	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
677	        return ownerMapper.toOwnerDto(owner);
678	    }
679	
680	    /**
681	     * Counts the members of the given owner's household - the owners that share this owner's
682	     * {@code householdId}, including the owner itself. An owner with no household ({@code householdId}
683	     * is {@code null}) is its own sole member, so the count is one.
684	     *
685	     * @param owner the owner whose household is being sized
686	     * @return the number of owners sharing this owner's household (one when it has no household)
687	     */
688	    private int countHouseholdMembers(Owner owner) {
689	        String householdId = owner.getHouseholdId();
690	        if (householdId == null) {
691	            return 1;
692	        }
693	        return (int) this.clinicService.findAllOwners().stream()
694	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
695	            .count();
696	    }
697	
698	    /**
699	     * Applies the household rule to an owner being created. A household is the set of owners sharing a
700	     * last name and a postcode: the {@code householdId} is derived deterministically from the
701	     * normalized last name and the postcode (see {@link #generateHouseholdId(String, String)}), so two
702	     * owners with the same last name and postcode always resolve to the same identifier and belong to
703	     * the same household automatically - no acknowledgement is needed to create the link.
704	     * <p>
705	     * When the owner supplies a postcode its {@code householdId} is always assigned. If that household
706	     * already has at least one member, the create is a household duplicate: it is rejected with a 409
707	     * unless {@code sharesHousehold} is true, in which case the owner is created as a declared member
708	     * of that household. An owner with no postcode belongs to no household and is left without an
709	     * identifier.
710	     *
711	     * @param owner the owner being created
712	     * @param sharesHousehold the request's shared-household acknowledgement, or {@code null} when absent
713	     * @return {@code true} when the owner joined an existing household as a declared member, otherwise
714	     *         {@code false}
715	     * @throws DuplicateOwnerHouseholdException when the household already exists and the create did not
716	     *         acknowledge it via {@code sharesHousehold}
717	     */
718	    private boolean applyHousehold(Owner owner, Boolean sharesHousehold) {
719	        String postcode = owner.getPostcode();
720	        if (postcode == null || postcode.isBlank()) {
721	            return false;
722	        }
723	        String lastName = normalizeHouseholdField(owner.getLastName());
724	        String householdId = generateHouseholdId(lastName, postcode);
725	        owner.setHouseholdId(householdId);
726	        boolean hasExistingMember = this.clinicService.findAllOwners().stream()
727	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
728	        if (!hasExistingMember) {
729	            return false;
730	        }
731	        if (!Boolean.TRUE.equals(sharesHousehold)) {
732	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), postcode);
733	        }
734	        return true;
735	    }
736	
737	    /**
738	     * Builds the stable identifier shared by the members of one household. It is derived purely from
739	     * the normalized last name and the postcode, so every owner sharing a last name and postcode
740	     * resolves to the same value - the first 12 upper-case hex characters of the SHA-256 digest of the
741	     * two fields joined by a single '|'.
742	     *
743	     * @param normalizedLastName the household's last name, already normalized for comparison
744	     * @param postcode the household's postcode
745	     * @return the shared household identifier
746	     */
747	    private String generateHouseholdId(String normalizedLastName, String postcode) {
748	        String key = normalizedLastName + '|' + postcode;
749	        try {
750	            byte[] digest = MessageDigest.getInstance("SHA-256")
751	                .digest(key.getBytes(StandardCharsets.UTF_8));
752	            StringBuilder hex = new StringBuilder();
753	            for (byte b : digest) {
754	                hex.append(String.format("%02X", b));
755	                if (hex.length() >= 12) {
756	                    break;
757	                }
758	            }
759	            return hex.substring(0, 12);
760	        } catch (NoSuchAlgorithmException e) {
761	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
762	        }
763	    }
764	
765	    /**
766	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the given
767	     * input's UTF-8 bytes. Used to derive the customer code's stable, deterministic hash component from
768	     * the owner's normalized telephone and last name.
769	     *
770	     * @param input the string to digest
771	     * @param length the number of leading upper-case hex characters to return
772	     * @return the first {@code length} upper-case hex characters of the SHA-256 digest
773	     */
774	    private String sha256UpperHex(String input, int length) {
775	        try {
776	            byte[] digest = MessageDigest.getInstance("SHA-256")
777	                .digest(input.getBytes(StandardCharsets.UTF_8));
778	            StringBuilder hex = new StringBuilder();
779	            for (byte b : digest) {
780	                hex.append(String.format("%02X", b));
781	                if (hex.length() >= length) {
782	                    break;
783	                }
784	            }
785	            return hex.substring(0, length);
786	        } catch (NoSuchAlgorithmException e) {
787	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
788	        }
789	    }
790	
791	    /**
792	     * Normalizes a last name for household comparison: surrounding whitespace is trimmed, each
793	     * internal run of whitespace is collapsed to a single space and the result is lower-cased.
794	     * Addresses use {@link #normalizeAddress(String)} instead, which additionally upper-cases and
795	     * expands common abbreviations.
796	     *
797	     * @param value the raw last name, or {@code null}
798	     * @return the normalized comparison key (empty string when {@code value} is {@code null})
799	     */
800	    private String normalizeHouseholdField(String value) {
801	        if (value == null) {
802	            return "";
803	        }
804	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
805	    }
806	}
